// Normalize form submit, gen booking_code, build wa.me link
// Soporta grupos multi-persona + modalidad de traslado (F5 · 2026-06-09)
let body = $input.item.json.body || $input.item.json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch(e) { body = {}; } }
body = body || {};

function genCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let r = 'EX-';
  for (let i = 0; i < 8; i++) r += chars[Math.floor(Math.random()*chars.length)];
  return r;
}

const booking_code = genCode();
const telYaz = '529984803595';

let servicios = body.servicios;
if (typeof servicios === 'string') servicios = [{ slug: servicios }];
if (!Array.isArray(servicios)) servicios = [];

// === F5: parseo de grupos + modalidad ===
const numPersonas = parseInt(body.num_personas || body.personas_total || 1, 10) || 1;
const isGroup = numPersonas >= 2;
const modalidad = body.modalidad || (isGroup ? 'simultaneo' : 'individual');
const numTerapeutas = body.num_terapeutas_estimado ? parseInt(body.num_terapeutas_estimado, 10) : null;
const costoTrasladoTotal = body.costo_traslado_total ? parseFloat(body.costo_traslado_total) : null;
let personasServicios = body.personas_servicios;
if (typeof personasServicios === 'string') {
  try { personasServicios = JSON.parse(personasServicios); } catch(e) { personasServicios = null; }
}
if (!Array.isArray(personasServicios) || personasServicios.length === 0) {
  // Fallback: si no viene desglose por persona, asumimos todos toman lo mismo
  personasServicios = isGroup
    ? Array.from({ length: numPersonas }, (_, i) => ({ persona_id: i + 1, label: 'Persona ' + (i + 1), servicios: servicios }))
    : [{ persona_id: 1, label: 'Persona 1', servicios: servicios }];
}

const servicioSlug = servicios[0]?.slug || 'masaje';
const pref = (body.preferencia_sexo || 'I').toUpperCase();
const zona = body.zona_colonia || 'Cancun';
const esDomicilio = body.tipo_cita === 'domicilio';

// === WhatsApp link estructurado — desglose por persona si es grupo ===
const waLines = [];
waLines.push('Hola, quiero reservar en Exentia.');
waLines.push('');
if (isGroup) {
  waLines.push('Grupo de ' + numPersonas + ' personas');
  if (esDomicilio) {
    const modLabel = ({ simultaneo: 'al mismo tiempo', turnos: 'por turnos', economica: 'la opcion mas economica' })[modalidad] || modalidad;
    waLines.push('Modalidad: ' + modLabel);
    if (numTerapeutas) waLines.push('Terapeutas estimadas: ' + numTerapeutas);
    if (costoTrasladoTotal) waLines.push('Traslado estimado: $' + costoTrasladoTotal);
  }
  waLines.push('');
  personasServicios.forEach(function(p){
    waLines.push(p.label + ':');
    var svcs = Array.isArray(p.servicios) ? p.servicios : [];
    if (svcs.length === 0) {
      waLines.push('- (sin servicios)');
    } else {
      svcs.forEach(function(s){ waLines.push('- ' + (s.slug || s.name || s)); });
    }
    waLines.push('');
  });
} else {
  waLines.push('Servicios:');
  if (servicios.length === 0) {
    waLines.push('- ' + servicioSlug);
  } else {
    servicios.forEach(function(s){ waLines.push('- ' + (s.slug || s.name || s)); });
  }
  waLines.push('');
}

if (esDomicilio) {
  waLines.push('Modalidad: A domicilio');
  if (body.direccion) waLines.push('Direccion: ' + body.direccion);
  else if (body.zona_colonia) waLines.push('Zona: ' + body.zona_colonia);
  if (body.direccion_maps_url) waLines.push('Maps: ' + body.direccion_maps_url);
} else {
  waLines.push('Modalidad: En sucursal');
  waLines.push('Plaza Hive - Av. Huayacan, Cancun');
}

const waText = waLines.join('\n').normalize('NFD').replace(/[̀-ͯ]/g,'');
const wa_link = 'https://wa.me/' + telYaz + '?text=' + encodeURIComponent(waText);

// Servicios como string comma-separated para GHL custom field
const serviciosStr = servicios.map(s => s.slug || s).filter(Boolean).join(',');

const telNormalized = (() => {
  const raw = body.cliente_telefono;
  if (!raw) return null;
  const d = String(raw).replace(/\D/g,'');
  if (!d) return null;
  if (d.length === 10) return '52' + d;
  if (d.length === 12 && d.startsWith('52')) return d;
  if (d.length === 13 && d.startsWith('521')) return '52' + d.slice(3);
  return d;
})();

const nombre = (body.cliente_nombre || '').trim();
const parts = nombre.split(' ');
const firstName = parts[0] || '';
const lastName = parts.slice(1).join(' ') || '';

return { json: {
  booking_code,
  wa_link,
  serviciosStr,
  firstName,
  lastName,
  phone: telNormalized,
  email: body.cliente_email || null,
  lead_ref: body.lead_ref || null,
  tipo_cita: body.tipo_cita || 'sucursal',
  direccion_maps_url: body.direccion_maps_url || null,
  zona_colonia: body.zona_colonia || null,
  num_personas: numPersonas,
  modalidad: modalidad,
  // For Postgres insert (will be completed with ghl_contact_id after upsert)
  rawPayload: {
    booking_code,
    lead_ref: body.lead_ref || null,
    cliente_nombre: body.cliente_nombre || null,
    cliente_telefono: telNormalized,
    cliente_email: body.cliente_email || null,
    servicios: servicios,
    preferencia_sexo: pref,
    zona_municipio: 'Cancun',
    zona_colonia: body.zona_colonia || null,
    direccion_libre: body.direccion || body.direccion_libre || null,
    direccion_maps_url: body.direccion_maps_url || null,
    latitud: body.lat ? parseFloat(body.lat) : null,
    longitud: body.lng ? parseFloat(body.lng) : null,
    notas_cliente: (body.tipo_cita === 'domicilio' ? ('[CITA A DOMICILIO] ' + (body.referencias ? 'Ref: ' + body.referencias + '. ' : '')) : '') + (body.notas_cliente || ''),
    modo_asignacion: body.tipo_cita === 'domicilio' ? 'domicilio' : 'whatsapp_group',
    estado: 'reservo',
    // F5: campos nuevos
    num_personas: numPersonas,
    modalidad: modalidad,
    num_terapeutas_estimado: numTerapeutas,
    costo_traslado_total: costoTrasladoTotal,
    personas_servicios: personasServicios
  }
} };

// Extract ghl_contact_id from upsert response and merge into payload BEFORE insert
const ghlResp = $input.first().json;
const contactId = ghlResp?.contact?.id || ghlResp?.contactId || null;
const norm = $('Normalize').item.json;

// Merge ghl_contact_id into the payload that Postgres will insert
const payload = Object.assign({}, norm.rawPayload, { ghl_contact_id: contactId });

return { json: {
  payload,
  ghl_contact_id: contactId,
  booking_code: norm.booking_code,
  wa_link: norm.wa_link
} };

// Build final response
const mergeData = $('Merge GHL ID').item.json;
const pgData = $input.first().json;

return [{ json: {
  success: true,
  booking_code: pgData.booking_code || mergeData.booking_code,
  id: pgData.id,
  wa_link: mergeData.wa_link,
  ghl_contact_id: pgData.ghl_contact_id || mergeData.ghl_contact_id
} }];
